-- public.set_market_leads
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.set_market_leads(p_market uuid, p_leads uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Only admins can set market leads'; end if;

  -- Demoted leads keep their membership: being removed as a lead is not being
  -- thrown out of the market.
  update public.community_members
     set role = 'creator'
   where community_id = p_market
     and role = 'manager'
     and (p_leads is null or not (profile_id = any (p_leads)));

  if p_leads is not null then
    insert into public.community_members (community_id, profile_id, role, status)
    select p_market, unnest(p_leads), 'manager', 'active'
    on conflict (community_id, profile_id)
    do update set role = 'manager', status = 'active';
  end if;
end;
$function$;
